+        Array.Copy(nonce, 0, result, 1, nonce.Length);
+        Array.Copy(tag, 0, result, 1 + nonce.Length, tag.Length);
+        Array.Copy(ciphertext, 0, result, 1 + nonce.Length + tag.Length, ciphertext.Length);
